create schema auth;
do $$begin if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin;end if;end$$;
create table auth.users(id uuid primary key);
create or replace function auth.uid() returns uuid language sql stable set search_path='' as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.organizations(id uuid primary key,name text);
create table public.profiles(id uuid primary key references auth.users(id),organization_id uuid references public.organizations(id),role text,active boolean);
create table public.clients(id uuid primary key,organization_id uuid not null references public.organizations(id),company_name text,status text,deleted_at timestamptz);
create table public.proposals(id uuid primary key,organization_id uuid,client_id uuid);
create table public.contracts(id uuid primary key default gen_random_uuid(),organization_id uuid not null,client_id uuid not null,proposal_id uuid,contract_number text,status text,signed boolean,signed_at date,start_date date,end_date date,minimum_term_months integer,billing_day integer,setup_value numeric,monthly_value numeric,total_value numeric,auto_renew boolean,renewal_status text,termination_date date,termination_reason text,notes text,legacy_id text,created_at timestamptz default now(),updated_at timestamptz default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table public.contract_services(id uuid primary key default gen_random_uuid(),organization_id uuid not null,contract_id uuid not null,service_catalog_id text,service_name text not null,service_category text,billing_type text,quantity numeric,unit_price numeric,monthly_value numeric,one_time_value numeric,setup_value numeric default 0,discount numeric default 0,total_value numeric,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.invoice_installments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,client_id uuid not null,contract_id uuid not null,proposal_id uuid,reference_month date not null,installment_number integer not null,due_date date not null,amount numeric not null,received_amount numeric not null default 0,status text,provider text,provider_invoice_id text,idempotency_key text,payment_url text,pix_copy_paste text,boleto_url text,paid_at timestamptz,cancelled_at timestamptz,payment_method text,payment_notes text,manual_confirmation_by uuid,manual_confirmation_at timestamptz,installment_type text default 'monthly',description text,source text,operational_notes text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(organization_id,contract_id,installment_type,reference_month));
create table public.commercial_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,client_id uuid,proposal_id uuid,contract_id uuid,installment_id uuid,event_type text not null,title text not null,description text,old_value jsonb,new_value jsonb,created_by uuid,created_at timestamptz default now());
create table public.data_merge_batches(id uuid primary key default gen_random_uuid(),organization_id uuid,request_key uuid,merge_type text default 'client',primary_client_id uuid,secondary_client_ids uuid[],reason text,approved_preview jsonb,status text,created_by uuid,created_at timestamptz default now(),completed_at timestamptz);
create table public.data_merge_items(id uuid primary key default gen_random_uuid(),organization_id uuid,batch_id uuid,table_name text,record_id uuid,action text,before_data jsonb,after_data jsonb,created_at timestamptz default now());
create or replace function public.current_organization_id() returns uuid language sql stable security definer set search_path='' as $$select organization_id from public.profiles where id=auth.uid() and active$$;
create or replace function public.current_user_role() returns text language sql stable security definer set search_path='' as $$select role from public.profiles where id=auth.uid() and active$$;
create or replace function public.can_write() returns boolean language sql stable set search_path='' as $$select public.current_user_role() in('admin','manager')$$;
create or replace function public.accounting_normalize_name(value text) returns text language sql immutable strict set search_path='' as $$select trim(regexp_replace(lower(translate(value,'áàâãäéèêëíìîïóòôõöúùûüç','aaaaaeeeeiiiiooooouuuuc')),'\s+',' ','g'))$$;
